#!/usr/bin/env node
// ITD-95 hash guard (ticket DoD, QA M2): every vendored upstream spec file must
// match its recorded hash — the upstream hash for byte-identical files, the
// replacement hash for the Tier C content-replaced file. If someone edits a
// vendored spec to make a test pass, this breaks the build (wired into
// `npm run lint`).
//
// Source of truth: spec/UPSTREAM_PROVENANCE.json (machine-readable sidecar of
// spec/UPSTREAM_PROVENANCE.md; both are regenerated by npm run upstream:baseline).

import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SIDE_PATH = path.join(ROOT, 'spec', 'UPSTREAM_PROVENANCE.json');

const sha256 = (p) => createHash('sha256').update(readFileSync(p)).digest('hex');

let failed = false;
const fail = (msg) => {
  process.stderr.write(`spec-integrity: ${msg}\n`);
  failed = true;
};

if (!existsSync(SIDE_PATH)) {
  fail(`missing ${path.relative(ROOT, SIDE_PATH)} (regenerate with: npm run upstream:baseline <sha>)`);
  process.exit(1);
}
const prov = JSON.parse(readFileSync(SIDE_PATH, 'utf8'));
const files = prov.files ?? {};
const replaced = prov.replaced ?? {};
let checked = 0;
for (const [rel, rec] of Object.entries(files)) {
  const abs = path.join(ROOT, rel);
  if (!existsSync(abs)) {
    fail(`${rel}: recorded in provenance but missing from the worktree`);
    continue;
  }
  const isReplaced = rec.mode === 'replaced' || rel in replaced;
  const expected = isReplaced ? replaced[rel]?.replacementSha256 : rec.sha256;
  if (!expected) {
    fail(`${rel}: ${isReplaced ? 'replaced' : 'upstream'} entry has no hash to check`);
    continue;
  }
  const actual = sha256(abs);
  if (actual !== expected) {
    fail(
      `${rel}: sha256 ${actual} != recorded ${isReplaced ? 'replacementSha256' : 'sha256'} ${expected} — vendored spec files are immutable; restore the file or re-baseline deliberately`,
    );
  }
  checked += 1;
}
if (failed) process.exit(1);
process.stdout.write(`spec-integrity: ${checked} vendored spec file(s) match their recorded hashes\n`);
